// src/view/actions/keyboard-shortcuts/helpers/keyboard-events/event-to-string.ts
var eventToString = (event) => {
  let string = event.key.toUpperCase();
  if (event.altKey)
    string += "Alt" /* Alt */;
  if (isMacLike) {
    if (event.ctrlKey)
      string += "Ctrl" /* Ctrl */;
    if (event.metaKey)
      string += "Mod" /* Mod */;
  } else {
    if (event.ctrlKey)
      string += "Mod" /* Mod */;
  }
  if (event.shiftKey)
    string += "Shift" /* Shift */;
  return string;
};

