// src/view/actions/markdown-preview/helpers/format-text.ts
var applyNbsp = (text2) => {
  const lines = text2.split("\n");
  let mutated = false;
  let isInCodeBlock = false;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith("```")) {
      isInCodeBlock = !isInCodeBlock;
    }
    if (isInCodeBlock)
      continue;
    if (lines[i].length > 0)
      continue;
    const previousLine = lines[i - 1];
    const skipNbsp = i > 0 && (previousLine.startsWith("- ") || previousLine.startsWith("> "));
    if (!skipNbsp) {
      lines[i] = "&nbsp;";
      mutated = true;
    }
  }
  return mutated ? lines.join("\n") : text2;
};
var formatText = (text2) => {
  if (/\s+(\^[a-zA-Z0-9]{4,})$/.test(text2)) {
    text2 = text2.replace(
      /\s+(\^[a-zA-Z0-9]{4,})$/gm,
      ' <sup class="cm-blockid" data-block-id="$1">$1</sup>'
    );
  }
  if (/%%/.test(text2)) {
    text2 = text2.replace(
      /%%(.*?)%%/gms,
      `<span class="cm-comment">%\u200B%$1%\u200B%</span>`
    );
  }
  if (/<!--/.test(text2)) {
    text2 = text2.replace(
      /<!--(.*?)-->/gms,
      '<span class="cm-comment">&lt;!--$1--&gt;</span>'
    );
  }
  if (/^\s*$/gm.test(text2) && !/^\|.*\|/m.test(text2)) {
    text2 = applyNbsp(text2);
  }
  return text2;
};

// src/view/actions/markdown-preview/helpers/mark-hidden-info-elements.ts
var ID_COMMENT_REGEX = /^<!--\s*ID:\s*\d{13}\s*-->$/;
var markHeadingLinkLine = (element2) => {
  const link = Array.from(element2.childNodes).find(
    (node) => node instanceof HTMLElement && node.matches("a.internal-link")
  );
  if (!link || link.parentElement !== element2)
    return false;
  const href = link.getAttribute("data-href") || link.getAttribute("href");
  if (!href || !href.includes("#"))
    return false;
  link.classList.add("lng-hidden-info-part");
  let next = link.nextSibling;
  while (next) {
    if (next.nodeType === Node.TEXT_NODE && next.textContent?.trim() === "") {
      next = next.nextSibling;
      continue;
    }
    if (next instanceof HTMLElement && next.tagName === "BR") {
      next.classList.add("lng-hidden-info-part");
      next = next.nextSibling;
      continue;
    }
    break;
  }
  return true;
};
var markHiddenInfoElements = (container) => {
  container.querySelectorAll("h4").forEach((heading) => {
    const next = heading.nextElementSibling;
    if (!next || next.tagName !== "P")
      return;
    markHeadingLinkLine(next);
  });
  container.querySelectorAll(".cm-comment").forEach((comment) => {
    const text2 = comment.textContent?.trim();
    if (!text2 || !ID_COMMENT_REGEX.test(text2))
      return;
    const target = comment.closest(".cm-comment") || comment;
    target.classList.add("lng-hidden-info-part");
  });
};

