// src/helpers/delay.ts
var delay = async (milliseconds, signal) => {
  return new Promise((resolve) => {
    const timeout = setTimeout(() => resolve(), milliseconds);
    if (signal) {
      signal.addEventListener("abort", () => {
        clearTimeout(timeout);
        resolve();
      });
    }
  });
};

