var MandalaTemplatesFileModal = class extends import_obsidian25.Modal {
  constructor(plugin, resolve) {
    super(plugin.app);
    this.plugin = plugin;
    this.resolve = resolve;
    this.resolved = false;
    this.folderSuggestEl = null;
    this.removeFolderSuggestListeners = null;
  }
  onOpen() {
    this.setTitle("\u6307\u5B9A\u6A21\u677F\u6587\u4EF6");
    const { contentEl } = this;
    contentEl.empty();
    let folderPath = "";
    const existingPath = this.plugin.settings.getValue().general.mandalaTemplatesFilePath;
    if (existingPath) {
      const lastSlash = existingPath.lastIndexOf("/");
      folderPath = lastSlash === -1 ? "" : existingPath.slice(0, lastSlash);
    }
    const folderSetting = new import_obsidian25.Setting(contentEl).setName("\u5B58\u653E\u6A21\u677F\u6587\u4EF6\u7684\u6587\u4EF6\u5939").setDesc("\u8BF7\u8F93\u5165\u5E93\u5185\u6587\u4EF6\u5939\u8DEF\u5F84\uFF1B\u7559\u7A7A\u8868\u793A\u6839\u76EE\u5F55").addText((text2) => {
      text2.setPlaceholder("\u4F8B\u5982\uFF1A3resources/templates");
      text2.setValue(folderPath);
      text2.onChange((value) => {
        folderPath = value.trim();
      });
    });
    folderSetting.settingEl.addClass("mandala-folder-suggest__setting");
    const folders = this.app.vault.getAllLoadedFiles().filter((file) => file instanceof import_obsidian25.TFolder).map((folder) => folder.path).filter((p) => p && p !== "/").sort((a, b) => a.localeCompare(b));
    const inputEl = folderSetting.controlEl.querySelector(
      "input"
    );
    const ensureSuggestEl = () => {
      if (this.folderSuggestEl)
        return this.folderSuggestEl;
      const el = document.createElement("div");
      el.className = "mandala-folder-suggest-float";
      el.setAttribute("role", "listbox");
      document.body.appendChild(el);
      this.folderSuggestEl = el;
      return el;
    };
    const hideSuggestions = () => {
      if (!this.folderSuggestEl)
        return;
      this.folderSuggestEl.remove();
      this.folderSuggestEl = null;
    };
    const positionSuggestEl = () => {
      if (!inputEl || !this.folderSuggestEl)
        return;
      const rect = inputEl.getBoundingClientRect();
      this.folderSuggestEl.style.left = `${Math.floor(rect.left)}px`;
      this.folderSuggestEl.style.top = `${Math.floor(rect.bottom + 6)}px`;
      this.folderSuggestEl.style.width = `${Math.floor(rect.width)}px`;
    };
    const renderSuggestions = (queryRaw) => {
      const query = queryRaw.trim().toLowerCase();
      if (!query) {
        hideSuggestions();
        return;
      }
      const startsWith = [];
      const includes = [];
      for (const p of folders) {
        const lower = p.toLowerCase();
        if (lower.startsWith(query)) {
          startsWith.push(p);
        } else if (lower.includes(query)) {
          includes.push(p);
        }
      }
      const matches = [...startsWith, ...includes].slice(0, 12);
      if (matches.length === 0) {
        hideSuggestions();
        return;
      }
      const suggestEl = ensureSuggestEl();
      suggestEl.textContent = "";
      positionSuggestEl();
      for (const match of matches) {
        const item = suggestEl.createEl("button", {
          cls: "mandala-folder-suggest__item",
          text: match
        });
        item.type = "button";
        item.setAttribute("role", "option");
        item.addEventListener("mousedown", (e) => {
          e.preventDefault();
        });
        item.addEventListener("click", () => {
          folderPath = match;
          if (inputEl)
            inputEl.value = match;
          hideSuggestions();
        });
      }
    };
    if (inputEl) {
      const onInput = () => renderSuggestions(inputEl.value);
      const onFocus = () => renderSuggestions(inputEl.value);
      const onBlur = () => window.setTimeout(() => hideSuggestions(), 120);
      const onWindowUpdate = () => positionSuggestEl();
      const onDocPointerDown = (e) => {
        const t = e.target;
        if (!t)
          return;
        if (t === inputEl)
          return;
        if (this.folderSuggestEl && this.folderSuggestEl.contains(t))
          return;
        hideSuggestions();
      };
      inputEl.addEventListener("input", onInput);
      inputEl.addEventListener("focus", onFocus);
      inputEl.addEventListener("blur", onBlur);
      window.addEventListener("resize", onWindowUpdate);
      window.addEventListener("scroll", onWindowUpdate, true);
      document.addEventListener("pointerdown", onDocPointerDown, true);
      this.removeFolderSuggestListeners = () => {
        inputEl.removeEventListener("input", onInput);
        inputEl.removeEventListener("focus", onFocus);
        inputEl.removeEventListener("blur", onBlur);
        window.removeEventListener("resize", onWindowUpdate);
        window.removeEventListener("scroll", onWindowUpdate, true);
        document.removeEventListener(
          "pointerdown",
          onDocPointerDown,
          true
        );
      };
    }
    new import_obsidian25.Setting(contentEl).setName("\u65B0\u5EFA\u6A21\u677F\u6587\u4EF6").setDesc("\u6587\u4EF6\u540D\u4E3A mandala-templates.md").addButton((button) => {
      button.setButtonText("\u65B0\u5EFA").setCta().onClick(async () => {
        const folder = this.getFolderFromPath(folderPath);
        if (!folder) {
          new import_obsidian25.Notice("\u672A\u627E\u5230\u8BE5\u6587\u4EF6\u5939\uFF0C\u8BF7\u68C0\u67E5\u8DEF\u5F84\u3002");
          return;
        }
        const existing = this.getTemplatesFileInFolder(folder);
        if (existing) {
          this.resolveOnce(existing);
          this.close();
          return;
        }
        const file = await this.createTemplateFile(folder);
        if (!file)
          return;
        this.resolveOnce(file);
        this.close();
      });
    });
    new import_obsidian25.Setting(contentEl).setName("\u9009\u62E9\u5DF2\u6709\u6A21\u677F\u6587\u4EF6").addButton((button) => {
      button.setButtonText("\u9009\u62E9").onClick(() => {
        const modal = new MandalaTemplatesFileSuggestModal(
          this.app,
          (file) => {
            this.resolveOnce(file);
            this.close();
          }
        );
        modal.open();
      });
    });
  }
  onClose() {
    this.resolveOnce(null);
    this.removeFolderSuggestListeners?.();
    this.removeFolderSuggestListeners = null;
    if (this.folderSuggestEl) {
      this.folderSuggestEl.remove();
      this.folderSuggestEl = null;
    }
    this.contentEl.empty();
  }
  async createTemplateFile(folder) {
    try {
      const content = "---\nmandala-templates: true\n---\n";
      return await createNewFile(
        this.plugin,
        folder,
        content,
        "mandala-templates"
      );
    } catch {
      new import_obsidian25.Notice("\u521B\u5EFA\u6A21\u677F\u6587\u4EF6\u5931\u8D25\u3002");
      return null;
    }
  }
  resolveOnce(value) {
    if (this.resolved)
      return;
    this.resolved = true;
    this.resolve(value);
  }
  getFolderFromPath(path) {
    if (!path)
      return this.app.vault.getRoot();
    const file = this.app.vault.getAbstractFileByPath(path);
    return file instanceof import_obsidian25.TFolder ? file : null;
  }
  getTemplatesFileInFolder(folder) {
    const folderPath = folder.path && folder.path !== "/" ? folder.path : "";
    const filePath = folderPath ? `${folderPath}/mandala-templates.md` : "mandala-templates.md";
    const file = this.app.vault.getAbstractFileByPath(filePath);
    return file instanceof import_obsidian25.TFile ? file : null;
  }
};
var MandalaTemplatesFileSuggestModal = class extends import_obsidian25.FuzzySuggestModal {
  constructor(app, onChoose) {
    super(app);
    this.onChoose = onChoose;
  }
  getItems() {
    return this.app.vault.getMarkdownFiles();
  }
  getItemText(item) {
    return item.path;
  }
  onChooseItem(item) {
    this.onChoose(item);
  }
};

